<?php require_once 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$st=$pdo->prepare("SELECT * FROM users WHERE email=?");$st->execute([strtolower(trim($_POST['email']))]);$u=$st->fetch();if($u&&password_verify($_POST['password'],$u['password'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];go($u['role']==='admin'?'admin/dashboard.php':'index.php');}else $err='Invalid email or password.';}$title='Login';include 'header.php';?><div class="row justify-content-center"><div class="col-md-6 panel"><h1>Welcome back</h1><?php if($err)echo '<div class="alert alert-danger">'.h($err).'</div>';?><form method="post"><input class="form-control mb-3" type="email" name="email" placeholder="Email" required><input class="form-control mb-3" type="password" name="password" placeholder="Password" required><button class="btn btn-rose">Login</button></form><p class="mt-3">New here? <a href="register.php">Create account</a></p></div></div><?php include 'footer.php'; ?>
